function kaprekar(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)||n<1||n>9999) return {error:'请输入 1–9999 的整数'};
  var s=String(n);
  while(s.length<4) s='0'+s;
  var digits=s.split('').map(Number);
  if(digits.every(function(d){return d===digits[0];})) return {error:'四位数字须不全相同'};
  var steps=0, cur=n;
  while(cur!==6174){
    var d=String(cur);
    while(d.length<4) d='0'+d;
    var arr=d.split('').map(Number).sort(function(a,b){return a-b;});
    var asc=+arr.join(''), desc=+arr.reverse().join('');
    cur=desc-asc; steps++;
    if(steps>100) break;
  }
  return {value:6174, steps:steps, origin:n};
}
var EXPORTS={kaprekar:kaprekar};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KaprekarForgePure = EXPORTS; }
